ALTER TABLE [dbo].[Countries] ADD [SortOrder] [int] NOT NULL DEFAULT 0
ALTER TABLE [dbo].[Dealers] ADD [SortOrder] [int] NOT NULL DEFAULT 0
Go

;WITH OrderedCountries AS
          (
              SELECT
                  Id,
                  ROW_NUMBER() OVER (
                      ORDER BY
                          CASE
                              WHEN Name IN ('USA', 'United States', 'Unite States') THEN 0
                              ELSE 1
                          END,
                          Name,
                          Id
                  ) AS RowNumber
              FROM dbo.Countries
          )
          UPDATE c
          SET SortOrder = oc.RowNumber * 10
          FROM dbo.Countries c
          INNER JOIN OrderedCountries oc ON c.Id = oc.Id;
Go

